import{j as e}from"./jsx-runtime-D_zvdyIk.js";import{r as m}from"./index-CXOcBcs0.js";import{L as g}from"./left-nav-CndNInsy.js";import{O as D,u as he,C as me}from"./create-new-outbound-mock-Bp2d4mcT.js";import{I as ue}from"./interaction-nav-item-BjPg2d3V.js";import{C as ge}from"./container-D8MK8QBE.js";import{C as fe}from"./content-area-sNeaqXFh.js";import{T as be}from"./tooltip-Cy9hcxi2.js";import{c as G}from"./utils-BLSKlp9E.js";import{H as ve}from"./house-7dsFQekL.js";import{S as we}from"./search-aUstRSOi.js";import{c as se}from"./createLucideIcon-DEcfmm_F.js";import{C as ae}from"./circle-help-Bj2MpUE2.js";import{S}from"./settings-Ddbozet5.js";import{M as ye}from"./monitor-DREitwVn.js";import{L as oe}from"./layout-grid-DIlLALBe.js";import{F as T}from"./file-text-D-AW36xm.js";import{G as xe}from"./gauge-CgEhWZVI.js";import{C as Ne}from"./chart-column-BD5V0Ndt.js";import"./_commonjsHelpers-CqkleIqs.js";import"./tree-menu-Clac48HE.js";import"./chevron-down-BRCsRsv-.js";import"./chevron-left-C6DiQdwt.js";import"./chevron-right-DZKRY3zX.js";import"./menu-B5sfcyl8.js";import"./index-DWcjTdiE.js";import"./index-DujEZ9g2.js";import"./menu-item-CR5qklhf.js";import"./scroll-chevron-DwoFwDLx.js";import"./chevron-up-DaHnz2kU.js";import"./input-B6wjqCOy.js";import"./error-icon-Jj0G9Pna.js";import"./label-DjGdKyh0.js";import"./popover-BOgfloWC.js";import"./index-5dOKg3EE.js";import"./index-DNfP5j1O.js";import"./index-C1YDQLuO.js";import"./Combination-CgjdYmp6.js";import"./tslib.es6-Ytcc2UEA.js";import"./container-header-BbK1XDO0.js";import"./x-N8aIqrq2.js";import"./select-C1iegF_x.js";import"./floating-ui.react-dom-B7A2Lg_k.js";import"./checkbox-B4rCSk8i.js";import"./index-CoT6TaLL.js";import"./minus-DYrWPnXn.js";import"./check-DrRFj5bn.js";import"./radio-button-group-By5ya3oH.js";import"./radio-BEZUIC79.js";import"./index-CWPvdnBY.js";import"./button-BxQnLjgV.js";import"./index-BDkVnVO1.js";import"./index-1evVQkiP.js";import"./badge-go1ZjKcF.js";import"./table-uygHRWkO.js";i